            logger.info("cancelled order %s", order_id)
        return self._snapshot(record, now)

    def extend(self, order_id: str, ttl: timedelta) -> Reservation:
        """Продлевает резерв: срок ``now + ttl``, но никогда не сокращается."""
        validate_ttl(ttl)
        now = self._clock.now()
        record = self._find(order_id)
        self._require_active(record, now)
        new_expires_at = now + ttl
        if new_expires_at > record.expires_at:
            expires = format_timestamp(new_expires_at)
            record.expires_at = new_expires_at
            self._log.append(now, "RESERVE_EXTEND", order=order_id, expires=expires)
            logger.info("extended order %s", order_id)
        return self._snapshot(record, now)

